document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("energy-form"),t=document.getElementById("energy-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("energy-m").value),o=parseFloat(document.getElementById("energy-h").value),d=parseFloat(document.getElementById("energy-v").value);if(n<0)return t.textContent="Mass cannot be negative.",void 0;const r=9.81*n*o,a=.5*n*d*d,i=r+a;t.innerHTML=`<b>Potential Energy (PE):</b> ${r.toFixed(3)} J<br><b>Kinetic Energy (KE):</b> ${a.toFixed(3)} J<br><b>Total Mechanical Energy:</b> ${i.toFixed(3)} J`})});